    "kind": "p",
    "image": null,
    "caption": "I skipped the obvious.\n\nNo Great Wall. No Beijing or Shanghai. No Terracotta Army..\n\nInstead, I headed south and west, through the karst landscapes of Yangshuo, the towering peaks of Zhangjiajie, the old streets of Lijiang and Fenghuang, and further into the mountains around Shangri-La, Tiger Leaping Gorge and Yading National Park.\n\nAnd somewhere along the way, China became one of the biggest travel surprises I’ve had!\n\nSave these places in case China ever makes it on your list. It’s absolutely worth it.\n\n#yangshuo #china #guilin #zhangjiajie #photography",
