  "image": "images/DZzuJp4OSP5.jpg",
  "caption": "📍 Shanghai Astronomy Museum, the world’s largest planetarium 🔭☄️🪐 If you love all things outerspace, this is a MUST visit!\n \nThings to know:\nIt is FAR. It’s about an hour or more away from the city centre, and there’s really not much out there except for the planetarium. I’d only go if a) you love outerspace, b) you have a lot of time in Shanghai, and/or c) it’s a rainy day and you have nothing to do.\n\nI’d say you can easily spend 2-4 hours here, more if you want to do the shows, workshops, etc. It’s not really possible to book shows for the dome theatre as a foreigner without a Chinese number",
