  "category": "Dorf",
  "note": "Klippendorf; am späten Nachmittag kommen, nach Sonnenuntergang beleuchtet. Mit Shanghai kombinierbar (Schnellzug nach Shangrao).",
  "address": "Shangrao, Jiangxi",
  "lat": 28.682859,
  "lng": 117.810253,
  "approx": false,
  "image": "images/DTWgwPiEvGy.jpg",
  "caption": "located deep in jiangxi province lies a thoughtfully designed tribute to the region’s history of mountain cultivation and reclusive scholars. a place shaped by taoist legend and carved into impossible terrain. \n\nwangxian (望仙) means “gazing at immortals,”draws from taoist lore. villages here were traditionally built along cliffs not only for protection, but to exist “closer” to the spiritual forces thought to inhabit the mountains.\n\nwalking through the valley after the village caught ablaze two days prior was a reminder of how fragile yet resilient these places are. albeit a modern recreation, ",
